"""Load configuration from files and strings."""

import os

from miniconf.errors import ConfigError
from miniconf.parser import parse_lines

_INCLUDE = "@include"


def _include_target(raw):
    """Return the include path if ``raw`` is an include directive, else None."""
    parts = raw.strip().split(None, 1)
    if not parts or parts[0] != _INCLUDE:
        return None
    if len(parts) < 2 or not parts[1].strip():
        raise ConfigError("@include requires a path")
    return parts[1].strip()


def _expand(path, stack, top_level):
    """Return the lines of ``path`` with ``@include`` directives expanded."""
    real = os.path.realpath(path)
    if real in stack:
        chain = " -> ".join(stack + [real])
        raise ConfigError("include cycle detected: {}".format(chain))
    try:
        with open(path, "r", encoding="utf-8") as fh:
            lines = fh.read().splitlines()
    except FileNotFoundError:
        if top_level:
            raise
        raise ConfigError("included file not found: {}".format(path))
    except (OSError, UnicodeDecodeError) as exc:
        if top_level:
            raise
        raise ConfigError("cannot read included file {}: {}".format(path, exc))

    base = os.path.dirname(real)
    out = []
    for raw in lines:
        target = _include_target(raw)
        if target is None:
            out.append(raw)
            continue
        out.extend(_expand(os.path.join(base, target), stack + [real], False))
    return out


def load(path):
    """Read and parse the configuration file at ``path``.

    ``@include <path>`` lines are replaced inline by the contents of the
    referenced file, resolved relative to the including file's directory.
    """
    path = os.fspath(path)
    return parse_lines(_expand(path, [], True))


def loads(text):
    """Parse configuration from a string."""
    return parse_lines(text.splitlines())
